const esc = (s: string) => s.replace(/[&<>"]/g, x => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;" }[x]!));
const parse = (text: string) => { const values=text.split(",").map(x=>Number(x.trim())); if (!values.length || values.some(x=>!Number.isFinite(x))) throw new Error("Use números reais finitos separados por vírgula."); return values; };
