function installStateSpaceEditor(side: HTMLElement): void {
  const section = document.createElement("section"); section.className = "model";
  const ss = project.plantStateSpace;
  section.innerHTML = `<details id="stateSpaceEditor"><summary>Planta em espaço de estados (SISO)</summary><p id="stateSpaceStatus" class="muted">${ss ? "Realização A/B/C/D ativa e preservada; análises usam o polinômio característico completo." : "A planta atual usa função de transferência."}</p><p class="muted">A é n×n; B e C têm n valores; D é escalar. Use vírgulas nas colunas e ponto e vírgula nas linhas de A.</p><label class="field">A<textarea id="ssA" rows="4" style="width:100%" placeholder="0, 1; -2, -3">${ss ? esc(ss.A.map(row => row.join(", ")).join("; ")) : ""}</textarea></label><label class="field">B<textarea id="ssB" rows="2" style="width:100%" placeholder="0, 1">${ss ? esc(ss.B.join(", ")) : ""}</textarea></label><label class="field">C<textarea id="ssC" rows="2" style="width:100%" placeholder="1, 0">${ss ? esc(ss.C.join(", ")) : ""}</textarea></label><label class="field">D<input id="ssD" type="number" step="any" value="${ss?.D ?? 0}"></label><label class="field">Estado inicial x₀<textarea id="ssX0" rows="2" style="width:100%" aria-label="Estado inicial da planta">${project.plantInitialState?.join(", ") ?? (ss ? ss.A.map(() => "0").join(", ") : "")}</textarea></label><button id="applyStateSpace" type="button">Aplicar planta em espaço de estados</button><button id="clearStateSpace" type="button">Voltar à função de transferência</button></details>`;
  side.insertBefore(section, document.getElementById("models"));
  section.querySelector<HTMLButtonElement>("#applyStateSpace")!.onclick = () => {
    try {
      const rows = (document.getElementById("ssA") as HTMLTextAreaElement).value.split(";").map(row => parse(row.trim()));
      const B = parse((document.getElementById("ssB") as HTMLTextAreaElement).value), C = parse((document.getElementById("ssC") as HTMLTextAreaElement).value), rawD = (document.getElementById("ssD") as HTMLInputElement).value.trim();
      if (!rawD) throw new Error("Informe o valor escalar D.");
      const D = Number(rawD);
      const initialText = (document.getElementById("ssX0") as HTMLTextAreaElement).value.trim();
      const initial = initialText ? parse(initialText) : rows.map(() => 0);
      if (initial.length !== rows.length) throw new Error(`x₀ deve conter ${rows.length} valores, um para cada estado.`);
      const realization = { A: rows, B, C, D, domain: project.domain, sampleTime: project.domain === "discrete" ? project.sampleTime : undefined };
      const equivalent = stateSpaceToTf(realization);
      project.plantStateSpace = { A: rows, B, C, D };
      project.plantInitialState = initial;
      project.G = { num: equivalent.num.join(", "), den: equivalent.den.join(", ") };
      document.getElementById("stateSpaceStatus")!.textContent = "Realização A/B/C/D ativa e preservada; análises usam o polinômio característico completo.";
      renderBindings(); markDirty(); analyze();
    } catch (error) { showError(error); }
  };
  section.querySelector<HTMLButtonElement>("#clearStateSpace")!.onclick = () => { delete project.plantStateSpace; delete project.plantInitialState; document.getElementById("stateSpaceStatus")!.textContent = "A planta atual usa função de transferência."; renderBindings(); markDirty(); analyze(); };
}
