function fullscreenIcon(exit:boolean){return `<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path fill="currentColor" d="${exit?"M8 4h2v6H4V8h4zm6 0h2v4h4v2h-6zM4 14h6v6H8v-4H4zm10 0h6v2h-4v4h-2z":"M4 4h6v2H6v4H4zm10 0h6v6h-2V6h-4zM4 14h2v4h4v2H4zm14 0h2v6h-6v-2h4z"}"/></svg>`}
function installGraphToggles(){
  const cards=Array.from(document.querySelectorAll<HTMLElement>(".plots .card"));
  cards.forEach((card,index)=>{
    const button=document.createElement("button");button.type="button";button.className="graph-fullscreen-toggle";button.innerHTML=fullscreenIcon(false);button.title="Expandir gr\u00e1fico";button.setAttribute("aria-label",`Expandir gr\u00e1fico ${index+1} para tela cheia`);button.setAttribute("aria-expanded","false");
    button.onclick=()=>{
      const expand=!card.classList.contains("fullscreen");
      cards.forEach((other,otherIndex)=>{
        other.classList.remove("fullscreen");const control=other.querySelector<HTMLButtonElement>(".graph-fullscreen-toggle");
        if(control){control.innerHTML=fullscreenIcon(false);control.title="Expandir gr\u00e1fico";control.setAttribute("aria-label",`Expandir gr\u00e1fico ${otherIndex+1} para tela cheia`);control.setAttribute("aria-expanded","false")}
      });
      if(expand){card.classList.add("fullscreen");button.innerHTML=fullscreenIcon(true);button.title="Reduzir gr\u00e1fico";button.setAttribute("aria-label",`Reduzir gr\u00e1fico ${index+1}`);button.setAttribute("aria-expanded","true")}
    };
    card.append(button);
  });
  if(!fullscreenEscapeHandlerInstalled){
    fullscreenEscapeHandlerInstalled=true;
    document.addEventListener("keydown",event=>{
      if(event.key!=="Escape")return;
      const expanded=document.querySelector<HTMLElement>(".plots .card.fullscreen");
      const toggle=expanded?.querySelector(".graph-fullscreen-toggle") as HTMLButtonElement | null | undefined;
      if(toggle){event.preventDefault();toggle.click();toggle.focus()}
    });
  }
}
